'use strict';
const C=StudyCore, chapters=window.COURSE||[],bank=chapters.flatMap(c=>c.questions.map(q=>({...q,chapter:c.id,file:c.file}))),qmap=new Map(bank.map(q=>[q.id,q])),app=document.querySelector('#app');
let state=C.fresh(),route='',tick=null,storageError='';
try{const saved=localStorage.getItem(C.KEY);if(saved)state=C.validate(JSON.parse(saved))}catch(e){storageError='Không đọc được dữ liệu đã lưu. Hãy nhập bản sao lưu nếu có.'}
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const para=s=>e(s).replace(/\n/g,'<br>');const list=a=>'<ul>'+a.map(x=>'<li>'+para(x)+'</li>').join('')+'</ul>';
const btn=(label,action,cls='')=>`<button class="btn ${cls}" data-action="${action}">${label}</button>`;
const minutes=ms=>`${Math.floor(ms/60000)} phút ${Math.floor(ms/1000)%60} giây`;
const chapter=id=>chapters.find(c=>c.id===id);const source=(c,p)=>`<div class="source">Nguồn: ${e(c.file)} · trang PDF ${e(p)}. Số trang tính từ đầu file.</div>`;
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.style.display='block';setTimeout(()=>el.style.display='none',3200)}
function save(){try{localStorage.setItem(C.KEY,JSON.stringify(state))}catch(err){storageError='Trình duyệt không lưu được dữ liệu. Hãy xuất bản sao lưu trước khi đóng trang.';toast(storageError)}}
function go(path){if(location.hash==='#'+path)render();else location.hash=path}
function pageTop(eyebrow,title,intro=''){return `<div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${intro?`<p class="intro">${intro}</p>`:''}`}
function progress(c){return c.sections.filter(s=>state.completed.includes(c.id+':'+s.id)).length}
function card(c){const done=progress(c),total=c.sections.length;return `<a class="card chapter-card" href="#lesson/${c.id}"><div class="chapter-top"><span class="chapter-number">BÀI ${e(c.id.toUpperCase())}</span><span class="chip">${done===total?'Đã học':done?'Đang học':'Bắt đầu'}</span></div><h3>${e(c.title)}</h3><p>${e(c.objectives[0])}</p><div class="progress"><b style="width:${done/total*100}%"></b></div><div class="chapter-meta"><span>${total} mục · ${c.questions.length} câu luyện tập</span><span>Học bài &nbsp;↗</span></div></a>`}
function home(){let total=chapters.reduce((n,c)=>n+c.sections.length,0),done=chapters.reduce((n,c)=>n+progress(c),0),last=state.history.at(-1),next=chapters.find(c=>progress(c)<c.sections.length)||chapters[0];app.innerHTML=`<section class="hero"><div><div class="eyebrow">HỌC HIỂU · LUYỆN NHỚ · TỰ TIN ĐI THI</div><h1>An toàn mạng.<br><em>Hiểu từ bản chất.</em></h1><p class="muted">Biến những slide nhiều lý thuyết thành kiến thức bạn có thể giải thích bằng lời của mình. Mỗi ngày, tiến thêm một chút.</p><div class="actions"><a class="btn primary" href="#lesson/${next.id}">${done?'Tiếp tục học':'Bắt đầu học'} &nbsp; →</a><a class="btn" href="#exam">Làm đề thi thử</a></div></div><div class="hero-visual" aria-hidden="true"><div class="orbit"></div><div class="shield">✓</div><div class="float-tag a">⌁ &nbsp;Hiểu cơ chế, nhớ lâu hơn</div><div class="float-tag b">◷ &nbsp;40 câu / 75 phút</div></div></section><div class="stats"><div class="stat"><span class="stat-icon">▤</span><div class="value">9</div><small>Bài học từ 802 trang slide</small></div><div class="stat"><span class="stat-icon">✓</span><div class="value">${Math.round(done/total*100)}<span class="tiny">%</span></div><small>${done}/${total} mục đã học</small></div><div class="stat"><span class="stat-icon">◇</span><div class="value">${bank.length}</div><small>Câu hỏi có giải thích</small></div><div class="stat"><span class="stat-icon">◷</span><div class="value">${state.history.length}</div><small>Lượt làm bài đã lưu</small></div></div>${state.active?`<div class="note"><strong>Bạn có bài đang làm dở.</strong> Câu trả lời và thời hạn được khôi phục khi tải lại trang. <a href="#session">Tiếp tục bài →</a></div>`:''}<div class="section-head"><h2>Lộ trình của bạn</h2><a href="#courses">Xem toàn bộ bài học ↗</a></div><div class="grid">${chapters.slice(0,6).map(card).join('')}</div><div class="two" style="margin-top:24px"><div class="card"><div class="eyebrow">GỢI Ý HỌC HIỆU QUẢ</div><h2>Hiểu trước. Chọn đáp án sau.</h2><p class="muted">Đọc một mục → giải thích lại không nhìn tài liệu → làm câu hỏi → xem lý do từng lựa chọn → ôn lại câu sai vào ngày hôm sau.</p><a href="#review">Mở sổ ôn tập →</a></div><div class="card"><div class="eyebrow">LẦN LUYỆN GẦN NHẤT</div>${last?`<h2>${C.grade(last,bank,last.ended).score.toFixed(2)}/10</h2><p class="muted">${e(last.title)}</p><a href="#result/${last.id}">Xem lại kết quả →</a>`:'<h2>Sẵn sàng thử sức?</h2><p class="muted">Bắt đầu từ một bài nhỏ. Mỗi câu sai là một điểm cần hiểu rõ hơn.</p><a href="#practice">Chọn bài luyện tập →</a>'}</div></div><div class="note">Lịch sử chỉ lưu trên trình duyệt và thiết bị này, không gửi lên máy chủ. Có thể mất khi xóa dữ liệu trình duyệt. <a href="#settings">Xuất / nhập bản sao lưu →</a></div>`}
function courses(){app.innerHTML=pageTop('GIÁO TRÌNH','Từng bài, từng bước.','Bám cấu trúc tài liệu gốc. Phần diễn giải, ví dụ và gợi ý học là học liệu biên soạn bổ trợ; nguồn slide được ghi ở từng mục.')+`<input class="search" id="courseSearch" placeholder="Tìm bài, khái niệm, nội dung…" aria-label="Tìm bài học"><div class="grid" id="courseGrid">${chapters.map(card).join('')}</div>`;document.querySelector('#courseSearch').oninput=ev=>{let t=ev.target.value.toLocaleLowerCase('vi');document.querySelector('#courseGrid').innerHTML=chapters.filter(c=>JSON.stringify(c).toLocaleLowerCase('vi').includes(t)).map(card).join('')}}
function externalNotes(c){return (c.external||[]).length?`<div class="note"><strong>Đối chiếu mở rộng · kiểm tra ngày 17/10/2026</strong>${c.external.map(x=>`<p><a href="${e(x.url)}" target="_blank" rel="noopener noreferrer">${e(x.title)} ↗</a><br>${e(x.note)}</p>`).join('')}</div>`:''}
function lesson(id){const c=chapter(id);if(!c)return go('courses');app.innerHTML=pageTop('GIÁO TRÌNH / BÀI '+e(id),e(c.title))+`<div class="two"><article class="lesson"><div class="card"><details><summary>Cấu trúc gốc trong slide</summary>${list((c.outline||[]).map((t,i)=>(i+1)+'. '+t))}<p class="tiny muted">Các mục dưới đây chia nhỏ thêm để dễ học; giữ nhóm mục gốc và liên kết trang tương ứng.</p></details><h3>Mục tiêu học tập</h3>${list(c.objectives)}<h3>Bức tranh tổng thể</h3><p>${para(c.overview)}</p>${source(c,'1–'+c.pages)}</div>${externalNotes(c)}${c.issues.length?`<details class="note warn"><summary>${c.issues.length} ghi chú nguồn cần lưu ý</summary>${list(c.issues.map(i=>'Trang '+i.page+': '+i.note))}</details>`:''}${c.sections.map(s=>`<section class="card lesson-section" id="section-${e(s.id)}"><div class="eyebrow">MỤC ${e(s.id)}</div><h2>${e(s.title)}</h2>${source(c,s.from+'–'+s.to)}<div class="explanation">${para(s.explanation)}</div><div class="plain"><strong>NÓI DỄ HIỂU</strong><p>${para(s.plain)}</p></div><div class="example"><strong>Ví dụ & liên hệ</strong><p>${para(s.example)}</p></div><h3>Điểm dễ sai khi làm trắc nghiệm</h3>${list(s.pitfalls)}<h3>Tự giải thích lại</h3>${list(s.recap)}<div class="actions">${btn(state.completed.includes(c.id+':'+s.id)?'✓ Đã học mục này':'Đánh dấu đã học','complete|'+c.id+'|'+s.id,'light')}${btn('Luyện tập mục này →','sectionPractice|'+c.id+'|'+s.id)}</div></section>`).join('')}${c.comparisons.map(t=>`<div class="card lesson-section"><h2>${e(t.title)}</h2><div class="table-wrap"><table><thead><tr>${t.headers.map(h=>'<th>'+e(h)+'</th>').join('')}</tr></thead><tbody>${t.rows.map(r=>'<tr>'+r.map(v=>'<td>'+para(v)+'</td>').join('')+'</tr>').join('')}</tbody></table></div></div>`).join('')}<section class="card"><h2>Cách học & ôn lại</h2>${list(c.study)}<div class="note">Tóm tắt cuối bài: dùng các câu “Tự giải thích lại” ở mỗi mục để tự kể lại toàn bộ bài mà không nhìn slide.</div><a class="btn primary" href="#practice/${c.id}">Luyện tập Bài ${e(c.id)} →</a></section></article><div class="card lesson-nav"><div class="eyebrow">TRONG BÀI NÀY</div>${c.sections.map(s=>`<a href="#lesson/${c.id}/${encodeURIComponent(s.id)}">${e(s.id)} · ${e(s.title)} ${state.completed.includes(c.id+':'+s.id)?'✓':''}</a>`).join('')}<div class="divider"></div><a href="#practice/${c.id}">◇ Luyện tập ${c.questions.length} câu</a><a href="#sources/${c.id}">▤ Bảng đối chiếu nguồn</a></div></div>`}
function terms(){let all=chapters.flatMap(c=>c.terms.map(t=>({...t,chapter:c.id})));app.innerHTML=pageTop('TỪ ĐIỂN','Gỡ rối thuật ngữ.','Giữ tên tiếng Anh, hiểu bằng tiếng Việt. Các diễn giải dưới đây là phần bổ trợ học tập.')+'<input class="search" id="termSearch" placeholder="Tìm tiếng Anh, tiếng Việt, chữ viết tắt…" aria-label="Tìm thuật ngữ"><div class="card" id="termResults"></div>';const draw=t=>{const found=all.filter(x=>JSON.stringify(x).toLowerCase().includes(t.toLowerCase()));document.querySelector('#termResults').innerHTML=found.length?found.map(x=>`<div class="term"><span class="chip">Bài ${e(x.chapter)}</span><h3>${e(x.en)}</h3><strong>${e(x.vi)}</strong><p class="muted">${para(x.meaning)}</p><a class="tiny" href="#lesson/${x.chapter}">Đọc trong bài →</a></div>`).join(''):'<p>Không tìm thấy thuật ngữ phù hợp.</p>'};draw('');document.querySelector('#termSearch').oninput=ev=>draw(ev.target.value)}
function practice(id){app.innerHTML=pageTop('LUYỆN TẬP','Biết vì sao mình chọn.','Luyện theo bài, chủ đề hoặc mức độ. Mỗi lựa chọn đều có giải thích sau khi bạn trả lời.')+`<div class="card"><div class="stack"><label>Bài học <select id="practiceChapter"><option value="all">Tất cả bài học</option>${chapters.map(c=>`<option value="${c.id}" ${c.id===id?'selected':''}>Bài ${c.id}: ${e(c.title)}</option>`).join('')}</select></label><label>Chủ đề <select id="practiceTopic"><option value="all">Tất cả chủ đề</option></select></label><label>Mức độ <select id="practiceLevel"><option value="all">Tất cả mức độ</option><option>Nhận biết</option><option>Thông hiểu</option><option>Vận dụng</option></select></label><label>Chế độ <select id="practiceMode"><option value="learn">Học có giải thích — xem ngay sau trả lời</option><option value="test">Tự kiểm tra — xem sau khi nộp</option></select></label><label>Số câu <select id="practiceCount"><option>10</option><option>20</option><option value="all">Tất cả câu phù hợp</option></select></label></div><div class="actions">${btn('Bắt đầu luyện tập →','startPractice','primary')}</div></div><div class="note">Không giới hạn thời gian ở chế độ luyện tập. Chấm điểm: đúng 1, sai hoặc bỏ trống 0; quy đổi thang 10 theo số câu.</div>`;const update=()=>{let ch=document.querySelector('#practiceChapter').value;let topics=[...new Set(bank.filter(q=>ch==='all'||q.chapter===ch).map(q=>q.topic))];document.querySelector('#practiceTopic').innerHTML='<option value="all">Tất cả chủ đề</option>'+topics.map(t=>`<option>${e(t)}</option>`).join('')};update();document.querySelector('#practiceChapter').onchange=update}
function exam(){let lv={};let fixed=C.makeExam(bank,true);for(let id of fixed){const l=qmap.get(id).level;lv[l]=(lv[l]||0)+1}app.innerHTML=pageTop('PHÒNG THI THỬ','40 câu. 75 phút.','Tập làm bài trong điều kiện thời gian thật. Đây là đề ôn tập được biên soạn, không phải đề thi chính thức.')+`<div class="two"><div class="card"><div class="eyebrow">QUY TẮC LÀM BÀI</div><h2>Thử sức khi bạn đã sẵn sàng.</h2>${list(['Đúng 40 câu, mỗi câu 4 lựa chọn và 1 đáp án đúng.','75 phút kể từ lúc bắt đầu; tải lại trang không đặt lại thời hạn.','Hết giờ tự nộp. Đáp án và lời giải chỉ mở sau khi nộp.','Điểm = số câu đúng × 0,25. Không trừ điểm câu sai hoặc bỏ trống.','Có thể đánh dấu để quay lại, chuyển câu bằng bảng điều hướng.'])}<div class="actions">${btn('Đề cố định A →','startExam|fixed','primary')}${btn('Tạo đề ngẫu nhiên','startExam|random')}</div><p class="tiny muted">Đề cố định dùng cùng câu và thứ tự để so sánh tiến bộ. Đề ngẫu nhiên ưu tiên câu chưa xuất hiện trong đề thi trước.</p></div><div class="card"><h3>Ma trận ôn tập đề xuất</h3><p class="tiny muted">Phân bổ theo phạm vi nội dung, tăng trọng số cho mật mã và giao thức; không suy ra từ đề thi thật.</p><table><tr><th>Bài</th><th>Tổng</th><th>NB / TH / VD</th></tr>${chapters.map(c=>`<tr><td>${e(c.id)} · ${e(c.title)}</td><td>${C.matrix[c.id]}</td><td>${C.levelMatrix[c.id].join(' / ')}</td></tr>`).join('')}<tr><th>Tổng</th><th>40</th><th>12 / 20 / 8</th></tr></table><p class="tiny">NB: nhận biết (30%) · TH: thông hiểu (50%) · VD: vận dụng (20%). Nếu bộ câu hỏi thay đổi và thiếu một mức độ, hệ thống dùng câu khác trong cùng bài; phân bổ thực tế của đề A được ghi dưới đây.</p><p class="tiny muted">Đề A thực tế: ${Object.entries(lv).map(([k,v])=>e(k)+': '+v).join(' · ')}.</p></div></div>`}
function begin(ids,mode,title){if(!ids.length)return toast('Chưa có câu hỏi phù hợp.');if(state.active&&!confirm('Bạn có bài đang làm dở. Thay bằng bài mới? Bài cũ chưa nộp sẽ không được lưu vào lịch sử.'))return;const now=Date.now();state.active={id:String(now),ids,mode,title,answers:{},flags:[],index:0,started:now,deadline:mode==='exam'?now+75*60000:null};save();go('session')}
function session(){const a=state.active;if(!a){app.innerHTML=pageTop('LÀM BÀI','Chưa có bài đang làm.')+'<a class="btn primary" href="#practice">Chọn bài luyện tập</a>';return}if(a.deadline&&Date.now()>=a.deadline)return submit(true);const q=qmap.get(a.ids[a.index]);if(!q){toast('Có câu hỏi không còn trong phiên bản học liệu. Hãy xuất sao lưu.');return go('settings')}let answered=Object.hasOwn(a.answers,q.id),reveal=a.mode==='learn'&&answered;app.innerHTML=pageTop(a.mode==='exam'?'THI THỬ / 40 CÂU · 75 PHÚT':'LUYỆN TẬP',e(a.title))+`<div class="quiz-layout"><div class="card"><div class="quiz-head"><span class="chip">Câu ${a.index+1} / ${a.ids.length}</span><span class="badge">Bài ${e(q.chapter)} · ${e(q.level)}</span></div><div class="question">${e(q.stem)}</div><div>${q.options.map((o,i)=>`<button class="option ${a.answers[q.id]===i?'selected':''} ${reveal?(i===q.correct?'right':a.answers[q.id]===i?'wrong':''):''}" aria-pressed="${a.answers[q.id]===i}" data-action="answer|${i}" ${reveal?'disabled':''}><b>${'ABCD'[i]}</b><span>${e(o)}</span></button>`).join('')}</div>${reveal?rationale(q):'<p class="tiny muted">Đáp án chưa được công bố.</p>'}<div class="actions">${btn('← Trước','prev')}${btn(a.flags.includes(q.id)?'★ Đã đánh dấu':'☆ Đánh dấu xem lại','flag')}${btn(a.index===a.ids.length-1?'Đến câu đầu ↻':'Tiếp theo →','next','primary')}</div></div><div class="card lesson-nav"><div class="quiz-head"><strong>${a.mode==='exam'?'Thời gian còn lại':'Tiến độ làm bài'}</strong></div><div id="timer" class="timer">${a.deadline?'':'Không giới hạn'}</div><p class="tiny muted">${Object.keys(a.answers).length}/${a.ids.length} câu đã trả lời</p><div class="qnav">${a.ids.map((id,i)=>`<button aria-label="Đến câu ${i+1}" class="${Object.hasOwn(a.answers,id)?'answered':''} ${a.flags.includes(id)?'flagged':''} ${i===a.index?'current':''}" data-action="jump|${i}">${i+1}</button>`).join('')}</div><p class="tiny muted">Xanh: đã trả lời · Gạch vàng: đánh dấu</p>${btn('Nộp bài','submit','primary')}<p class="tiny muted">Tự lưu sau mỗi thao tác.</p></div></div>`;if(a.deadline){updateTimer();tick=setInterval(updateTimer,1000)}}
function updateTimer(){let a=state.active;if(!a||!a.deadline)return;const remaining=a.deadline-Date.now();if(remaining<=0){clearInterval(tick);return submit(true)}let el=document.querySelector('#timer');if(el){el.textContent=Math.floor(remaining/60000)+':'+String(Math.floor(remaining/1000)%60).padStart(2,'0');el.classList.toggle('urgent',remaining<5*60000)}}
function rationale(q){return `<div class="rationale"><strong>Đáp án đúng: ${'ABCD'[q.correct]} · ${e(q.options[q.correct])}</strong>${q.explanations.map((x,i)=>`<p class="${i===q.correct?'correct':''}"><strong>${'ABCD'[i]}.</strong> ${para(x)}</p>`).join('')}${source(chapter(q.chapter),q.page)}<a class="tiny" href="#lesson/${q.chapter}/${encodeURIComponent(q.section)}">Học lại mục liên quan →</a></div>`}
function submit(auto=false){const a=state.active;if(!a)return;if(!auto&&!confirm('Nộp bài và xem kết quả? Bạn không thể sửa đáp án sau khi nộp.'))return;clearInterval(tick);a.ended=Math.min(Date.now(),a.deadline||Date.now());a.auto=auto;state.history.push(a);for(const id of a.flags)if(!state.marked.includes(id))state.marked.push(id);if(a.mode==='exam')state.seen=[...new Set([...state.seen,...a.ids])];state.active=null;save();go('result/'+a.id)}
function result(id){const a=state.history.find(h=>h.id===id);if(!a)return go('history');let g=C.grade(a,bank,a.ended),weak=Object.entries(g.topics).filter(([_,v])=>v.correct/v.total<.7);app.innerHTML=pageTop('KẾT QUẢ',e(a.title),new Date(a.ended).toLocaleString('vi-VN'))+`<div class="card result-banner"><div class="score">${g.score.toFixed(2)}<span class="tiny">/10</span></div><div><h2>${g.correct}/${g.total} câu đúng · ${g.rate.toFixed(1)}%</h2><p class="muted">${g.wrong} sai · ${g.blank} bỏ trống · ${minutes(g.elapsed)}</p><p class="tiny">Điểm = số câu đúng / tổng số câu × 10. Không trừ điểm.</p>${a.auto?'<p class="tiny">Bài được tự nộp khi hết giờ.</p>':''}</div></div><div class="section-head"><h2>Nhìn lại theo chủ đề</h2></div><div class="card"><div class="table-wrap"><table><tr><th>Chủ đề</th><th>Đúng</th><th>Tỷ lệ</th><th>Ôn lại</th></tr>${Object.entries(g.topics).map(([k,v])=>`<tr><td>${e(k)}</td><td>${v.correct}/${v.total}</td><td>${Math.round(v.correct/v.total*100)}%</td><td><a href="#lesson/${v.chapter}">Bài ${v.chapter} →</a></td></tr>`).join('')}</table></div>${weak.length?`<div class="note">Ưu tiên ôn: ${weak.map(([k])=>e(k)).join('; ')}. Đọc lại cơ chế, tự giải thích rồi làm lại câu sai.</div>`:'<div class="note">Bạn đã đạt ít nhất 70% ở các chủ đề của lượt này. Hãy thử thêm đề khác để kiểm tra độ vững.</div>'}</div><div class="section-head"><h2>Đáp án & lời giải từng câu</h2>${btn('Luyện lại câu sai / bỏ trống','retry|'+a.id)}</div>${a.ids.map((qid,i)=>{const q=qmap.get(qid);if(!q)return `<div class="note warn">Câu ${i+1} không còn trong học liệu hiện tại.</div>`;const answer=a.answers[qid];return `<div class="card review-item"><span class="chip">Câu ${i+1} · ${answer===undefined?'Bỏ trống':answer===q.correct?'Đúng':'Sai'}</span><h3>${e(q.stem)}</h3><p class="tiny">Bạn chọn: ${answer===undefined?'Chưa trả lời':'ABCD'[answer]+' · '+e(q.options[answer])}</p>${rationale(q)}${btn(state.marked.includes(q.id)?'★ Bỏ đánh dấu':'☆ Lưu câu này','mark|'+q.id)}</div>`}).join('')}`}
function historyPage(){app.innerHTML=pageTop('LỊCH SỬ','Nhìn thấy mình tiến bộ.','Lưu riêng trên thiết bị này. Bạn có thể mở lại toàn bộ câu trả lời và lời giải.')+(state.history.length?`<div class="card table-wrap"><table><tr><th>Thời điểm nộp</th><th>Loại / Bài</th><th>Điểm</th><th>Thời gian</th><th></th></tr>${[...state.history].reverse().map(h=>{const g=C.grade(h,bank,h.ended);return `<tr><td>${e(new Date(h.ended).toLocaleString('vi-VN'))}</td><td>${e(h.mode==='exam'?'Thi thử':h.mode==='learn'?'Học có giải thích':'Tự kiểm tra')}<br>${e(h.title)}</td><td>${g.score.toFixed(2)}/10</td><td>${minutes(g.elapsed)}</td><td><a href="#result/${h.id}">Chi tiết →</a></td></tr>`}).join('')}</table></div>`:'<div class="card empty">Chưa có lượt làm bài nào. <a href="#practice">Bắt đầu luyện tập →</a></div>')}
function wrongIds(){const latest=new Map();for(const h of state.history)for(const id of h.ids){const q=qmap.get(id);if(q)latest.set(id,h.answers[id]!==q.correct)}return [...latest].filter(([_,bad])=>bad).map(([id])=>id)}
function review(){let wrong=wrongIds(),marked=state.marked.filter(id=>qmap.has(id)),topics={};for(let id of wrong){let q=qmap.get(id);topics[q.chapter+' · '+q.topic]=(topics[q.chapter+' · '+q.topic]||0)+1}app.innerHTML=pageTop('SỔ ÔN TẬP','Biến câu sai thành điểm mạnh.','Câu sai dựa trên lần trả lời gần nhất của từng câu; trả lời đúng khi luyện lại sẽ gỡ khỏi danh sách này.')+`<div class="stats"><div class="stat"><div class="value">${wrong.length}</div><small>Câu sai / chưa trả lời cần ôn</small></div><div class="stat"><div class="value">${marked.length}</div><small>Câu đã đánh dấu</small></div></div><div class="actions">${btn('Luyện câu sai','reviewWrong','primary')}${btn('Luyện câu đánh dấu','reviewMarked')}</div><div class="section-head"><h2>Chủ đề cần củng cố</h2></div><div class="card">${Object.entries(topics).length?Object.entries(topics).sort((a,b)=>b[1]-a[1]).map(([k,n])=>`<p>${e(k)} <span class="chip">${n} câu</span> <a href="#lesson/${k.split(' · ')[0]}">Học lại →</a></p>`).join(''):'<p class="muted">Chưa có chủ đề cần ôn từ lịch sử hiện tại.</p>'}</div><div class="section-head"><h2>Câu đã lưu</h2></div>${marked.map(id=>{const q=qmap.get(id);return `<div class="card review-item"><span class="chip">Bài ${q.chapter} · ${e(q.topic)}</span><h3>${e(q.stem)}</h3>${btn('Luyện câu này','single|'+id)} ${btn('Bỏ đánh dấu','mark|'+id)}</div>`}).join('')||'<div class="card empty">Nhấn ☆ ở câu hỏi để lưu vào đây.</div>'}`}
function sources(id){const cs=id?[chapter(id)].filter(Boolean):chapters;app.innerHTML=pageTop('NGUỒN & ĐỘ BAO PHỦ','Bản đồ tài liệu.','Số trang là vị trí trong file PDF, gồm cả trang bìa. Các phần diễn giải dễ hiểu, ví dụ và câu hỏi là nội dung biên soạn dựa trên nguồn, không phải nguyên văn slide.')+`<div class="note">Đã nhận đủ 9 tài liệu. Những trang bìa, mục lục và chuyển mục được quản lý trong bảng trang gốc; nội dung chuyên môn được đối chiếu theo các mục dưới đây. Ghi chú xác minh được hiển thị riêng, không xem là nội dung đã xác thực.</div>${cs.map(c=>`<div class="card review-item"><h2>Bài ${c.id} · ${e(c.title)}</h2>${source(c,'1–'+c.pages)}${externalNotes(c)}<div class="table-wrap"><table><tr><th>Mục học</th><th>Trang PDF</th><th>Câu luyện</th></tr>${c.sections.map(s=>`<tr><td><a href="#lesson/${c.id}/${encodeURIComponent(s.id)}">${e(s.id)} · ${e(s.title)}</a></td><td>${s.from}–${s.to}</td><td>${c.questions.filter(q=>q.section===s.id).length}</td></tr>`).join('')}</table></div>${c.issues.length?`<div class="note warn">${list(c.issues.map(i=>'Trang '+i.page+': '+i.note))}</div>`:''}<details><summary>Đối chiếu từng trang gốc</summary><div class="table-wrap"><table><tr><th>Trang</th><th>Tiêu đề / văn bản nhận diện</th><th>Ánh xạ bài học</th></tr>${(window.SOURCE_PAGES?.[c.id]||[]).map(p=>{const matches=c.sections.filter(s=>p.page>=s.from&&p.page<=s.to);return `<tr class="coverage-row"><td>${p.page}</td><td>${e(p.heading||'Trang ảnh / ít văn bản — xem ghi chú nguồn')}</td><td>${matches.map(s=>e(s.id)).join(', ')||'Bìa / mục lục / chuyển mục hoặc cần đối chiếu'}</td></tr>`}).join('')}</table></div></details></div>`).join('')}`}
function settings(){app.innerHTML=pageTop('DỮ LIỆU CÁ NHÂN','Giữ lại hành trình học.','Website công khai; tiến độ và lịch sử của bạn không được đưa lên máy chủ.')+`<div class="card"><h2>Cơ chế lưu trên trình duyệt</h2>${list(['Dữ liệu nằm trong localStorage của trình duyệt hiện tại, trên đúng thiết bị và địa chỉ website này.','Không có tài khoản hoặc đồng bộ giữa các thiết bị. Người cùng dùng hồ sơ trình duyệt có thể xem lịch sử ở đây.','Xóa dữ liệu website, chế độ riêng tư hoặc đổi trình duyệt có thể làm mất dữ liệu. Hãy xuất bản sao lưu định kỳ.','Bài thi lưu thời điểm kết thúc tuyệt đối. Đóng trang không dừng đồng hồ; mở lại sau hạn sẽ tự nộp.','Bổ sung học liệu dùng mã bài/câu ổn định; tiến độ và lịch sử hiện có được giữ lại khi cập nhật.'])}<div class="actions">${btn('↓ Xuất bản sao lưu JSON','export','primary')}${btn('↑ Nhập bản sao lưu','import')}</div><input id="importFile" type="file" accept="application/json,.json"><p class="tiny muted">Nhập sao lưu sẽ thay dữ liệu hiện tại sau khi xác nhận. Nên xuất bản hiện tại trước.</p></div><div class="card review-item"><h2>Bổ sung tài liệu sau này</h2><p>Gửi thêm file trong cuộc trò chuyện để cập nhật website. Bản cập nhật giữ mã bài và câu hiện có, bổ sung mục mới và cập nhật bảng đối chiếu nguồn. Xuất sao lưu trước mỗi lần thay đổi lớn.</p><a href="#sources">Xem danh mục nguồn →</a></div>`;document.querySelector('#importFile').onchange=async ev=>{try{const f=ev.target.files[0];if(!f)return;if(f.size>20e6)throw Error('Tệp sao lưu quá lớn.');const candidate=C.validate(JSON.parse(await f.text()));const unknown=[...candidate.marked,...candidate.history.flatMap(h=>h.ids),...(candidate.active?.ids||[])].filter(id=>!qmap.has(id));if(unknown.length)throw Error('Bản sao lưu chứa câu hỏi không có trong phiên bản học liệu này.');if(!confirm('Thay dữ liệu hiện tại bằng bản sao lưu này?'))return;state=candidate;save();toast('Đã khôi phục bản sao lưu.');render()}catch(err){toast(err.message)}}}
function render(){clearInterval(tick);if(state.active?.deadline&&Date.now()>=state.active.deadline){submit(true);return}route=location.hash.slice(1)||'home';const [page,id,sectionId]=route.split('/');const nav=[['home','⌂','Tổng quan'],['courses','▤','Giáo trình'],['terms','⌕','Thuật ngữ'],['practice','◇','Luyện tập'],['exam','◷','Thi thử'],['review','☆','Sổ ôn tập'],['history','↺','Lịch sử'],['sources','▦','Nguồn tài liệu'],['settings','⚙','Dữ liệu cá nhân']];document.querySelector('#nav').innerHTML=nav.map(([k,i,t])=>`<a class="${page===k||(k==='courses'&&page==='lesson')?'active':''}" href="#${k}"><i>${i}</i>${t}</a>`).join('');if(page==='session')session();else if(page==='lesson')lesson(id);else if(page==='courses')courses();else if(page==='terms')terms();else if(page==='practice')practice(id);else if(page==='exam')exam();else if(page==='history')historyPage();else if(page==='review')review();else if(page==='result')result(id);else if(page==='sources')sources(id);else if(page==='settings')settings();else home();if(storageError)app.insertAdjacentHTML('afterbegin',`<div class="note error">${e(storageError)}</div>`);if(sectionId){requestAnimationFrame(()=>document.getElementById('section-'+decodeURIComponent(sectionId))?.scrollIntoView())}else window.scrollTo(0,0)}
app.addEventListener('click',ev=>{const b=ev.target.closest('[data-action]');if(!b)return;const [action,...args]=b.dataset.action.split('|');const a=state.active;switch(action){case 'complete':{const key=args[0]+':'+args[1];state.completed=state.completed.includes(key)?state.completed.filter(x=>x!==key):[...state.completed,key];save();const y=scrollY;render();scrollTo(0,y);break}case 'sectionPractice':{const qs=bank.filter(q=>q.chapter===args[0]&&q.section===args[1]);if(!qs.length)return go('practice/'+args[0]);begin(C.shuffle(qs).map(q=>q.id),'learn','Bài '+args[0]+' · Mục '+args[1]);break}case 'startPractice':{const val=id=>document.querySelector('#'+id).value,ch=val('practiceChapter'),topic=val('practiceTopic'),level=val('practiceLevel');let qs=C.shuffle(bank.filter(q=>(ch==='all'||q.chapter===ch)&&(topic==='all'||q.topic===topic)&&(level==='all'||q.level===level)));const n=val('practiceCount');if(n!=='all')qs=qs.slice(0,Number(n));begin(qs.map(q=>q.id),val('practiceMode'),ch==='all'?'Luyện tập tổng hợp':'Luyện tập Bài '+ch);break}case 'startExam':begin(C.makeExam(bank,args[0]==='fixed',state.seen),'exam',args[0]==='fixed'?'Đề cố định A':'Đề ngẫu nhiên');break;case 'answer':if(a){const q=qmap.get(a.ids[a.index]);if(a.mode==='learn'&&Object.hasOwn(a.answers,q.id))return;a.answers[q.id]=Number(args[0]);save();const y=scrollY;render();scrollTo(0,y)}break;case 'flag':if(a){const id=a.ids[a.index];a.flags=a.flags.includes(id)?a.flags.filter(x=>x!==id):[...a.flags,id];save();render()}break;case 'jump':if(a){a.index=Number(args[0]);save();render()}break;case 'prev':if(a){a.index=Math.max(0,a.index-1);save();render()}break;case 'next':if(a){a.index=(a.index+1)%a.ids.length;save();render()}break;case 'submit':submit();break;case 'mark':state.marked=state.marked.includes(args[0])?state.marked.filter(x=>x!==args[0]):[...state.marked,args[0]];save();{const y=scrollY;render();scrollTo(0,y)}break;case 'retry':{const h=state.history.find(h=>h.id===args[0]);begin(h.ids.filter(id=>h.answers[id]!==qmap.get(id)?.correct),'learn','Ôn lại câu sai / bỏ trống');break}case 'reviewWrong':begin(C.shuffle(wrongIds()),'learn','Ôn lại câu sai');break;case 'reviewMarked':begin(C.shuffle(state.marked.filter(id=>qmap.has(id))),'learn','Ôn câu đã đánh dấu');break;case 'single':begin([args[0]],'learn','Ôn câu đã lưu');break;case 'export':{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='netstudy-sao-luu-'+new Date().toISOString().slice(0,10)+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Đã xuất bản sao lưu.');break}case 'import':document.querySelector('#importFile').click();break}});
window.addEventListener('hashchange',render);window.addEventListener('focus',()=>{if(state.active?.deadline&&Date.now()>=state.active.deadline)submit(true)});document.addEventListener('visibilitychange',()=>{if(!document.hidden&&state.active?.deadline&&Date.now()>=state.active.deadline)submit(true)});render();

setInterval(()=>{if(state.active?.deadline&&Date.now()>=state.active.deadline)submit(true)},1000);
